package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStderr string
	}{
		{"no args", []string{}, 2, "Usage:"},
		{"unknown command", []string{"explode"}, 2, "unknown command"},
		{"get missing key", []string{"get"}, 2, "requires a key"},
		{"set missing value", []string{"set", "foo"}, 2, "requires key and value"},
		{"delete missing key", []string{"delete"}, 2, "requires a key"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			got := cli.Run(tt.args)
			if got != tt.wantExit {
				t.Errorf("exit code = %d, want %d", got, tt.wantExit)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_InitCommand(t *testing.T) {
	t.Run("creates config file", func(t *testing.T) {
		dir := t.TempDir()
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})
		if exit != 0 {
			t.Fatalf("exit = %d, stderr = %s", exit, stderr.String())
		}

		configPath := filepath.Join(dir, "config.yaml")
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("fails if exists", func(t *testing.T) {
		dir := t.TempDir()
		configPath := filepath.Join(dir, "config.yaml")
		os.WriteFile(configPath, []byte("existing: true"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})
		if exit != 1 {
			t.Errorf("expected exit 1, got %d", exit)
		}
	})
}

func TestCLI_GetSetDelete(t *testing.T) {
	dir := t.TempDir()
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, dir)

	// Set a value
	if exit := cli.Run([]string{"set", "doctor", "cochran"}); exit != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get it back
	stdout.Reset()
	if exit := cli.Run([]string{"get", "doctor"}); exit != 0 {
		t.Fatalf("get failed: %s", stderr.String())
	}
	if got := stdout.String(); got != "cochran\n" {
		t.Errorf("get = %q, want %q", got, "cochran\n")
	}

	// Delete it
	if exit := cli.Run([]string{"delete", "doctor"}); exit != 0 {
		t.Fatalf("delete failed: %s", stderr.String())
	}

	// Verify gone
	stderr.Reset()
	if exit := cli.Run([]string{"get", "doctor"}); exit != 1 {
		t.Error("expected key not found")
	}
}

func TestCLI_ValidateInvalidYAML(t *testing.T) {
	dir := t.TempDir()
	configPath := filepath.Join(dir, "config.yaml")
	os.WriteFile(configPath, []byte("invalid: yaml: ::broken"), 0644)

	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, dir)

	exit := cli.Run([]string{"validate"})
	if exit != 1 {
		t.Errorf("expected exit 1 for invalid YAML, got %d", exit)
	}
	if !bytes.Contains(stderr.Bytes(), []byte("invalid YAML")) {
		t.Errorf("expected invalid YAML error, got: %s", stderr.String())
	}
}

func TestCLI_OutputFormats(t *testing.T) {
	dir := t.TempDir()
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, dir)
	cli.Run([]string{"set", "test", "value"})

	for _, format := range []string{"json", "yaml", "text"} {
		stdout.Reset()
		exit := cli.Run([]string{"--format", format, "list"})
		if exit != 0 {
			t.Errorf("%s format failed: %s", format, stderr.String())
		}
	}
}
